def check_win(board, player):
    return any(all(board[r][c] == player for r, c in line) for line in lines)

memo = {}

def minimax(board, is_x_turn):
    state = tuple(tuple(row) for row in board) + (is_x_turn,)
    if state in memo:
        return memo[state]

    if check_win(board, 'O'):
        return -1
    if check_win(board, 'X'):
        return 1

    empty = [(r, c) for r in range(3) for c in range(3) if board[r][c] == '.']
    if not empty:
        # Should never reach here without a win
        return 0

    if is_x_turn:
        best = -2
        for r, c in empty:
            board[r][c] = 'X'
            score = minimax(board, False)
            board[r][c] = '.'
            if score > best:
                best = score
            if best == 1:
                break
        memo[state] = best
        return best
    else:
